-- PREVIEW ONLY: forward-only removal of observed excess object privileges.
DO $r75_scope$ BEGIN
 IF current_database()<>'postgres' OR session_user<>'postgres' OR current_user<>'postgres' OR (SELECT rolsuper FROM pg_roles WHERE rolname=current_user) THEN RAISE EXCEPTION 'R75_DIRECT_PREVIEW_MAINTENANCE_ACTOR_REQUIRED'; END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('fgttffyrkabpycmbnppi:acl-repair-r75',0)) THEN RAISE EXCEPTION 'R75_REPAIR_CONCURRENT'; END IF;
 IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>1 OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261030205748' AND encode(sha256(convert_to(array_to_string(statements,E'\n'),'UTF8')),'hex')='5ed9df1fa01150fae47990937b15d434409ccf68cff0fd16e0779da6c5f8701c') THEN RAISE EXCEPTION 'R75_EXACT_BASELINE_HISTORY_REQUIRED_NO_REAPPLICATION'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.logs_auditoria WHERE id='c17d7c2a-2ee6-4bde-b580-1b8950b717b5'::uuid AND origem='preview_baseline_r73' AND dados_depois->>'intended_project_ref'='fgttffyrkabpycmbnppi' AND dados_depois->>'intended_branch_id'='5cb53ebc-edf6-43f5-a970-9eb4471c4f17' AND dados_depois->>'body_sha256'='5ed9df1fa01150fae47990937b15d434409ccf68cff0fd16e0779da6c5f8701c') THEN RAISE EXCEPTION 'R75_PREVIEW_BASELINE_RECEIPT_REQUIRED'; END IF;
 IF (SELECT count(*) FROM public.nfe_fiscal_provider_state WHERE provider='SERPRO' AND capability_state='UNVERIFIED' AND consumption_mode='OFF_ZERO_BUDGET' AND circuit_state='OPEN' AND cutover_at IS NULL AND calls_today=0 AND daily_budget=0 AND oauth_dispatch_count=0 AND get_dispatch_count=0 AND http_response_count=0)<>1 THEN RAISE EXCEPTION 'R75_SERPRO_MUST_REMAIN_OFF'; END IF;
END $r75_scope$;
